const j = $json;
const ev = j.event || j;
let text = (ev.text || j.text || '').trim();

text = text
  .replace(/<@[^>]+>/g, '')
  .replace(/<#[^|>]+\|([^>]+)>/g, '$1')
  .replace(/<([^|>]+)\|([^>]+)>/g, '$2')
  .replace(/<([^>]+)>/g, '$1')
  .replace(/[“”]/g, '"')
  .trim();

const TZ_OFFSET = '+09:00';
const now = new Date();
const thisYear = now.getFullYear();
function pad(n) { return String(n).padStart(2, '0'); }

// --- 날짜 ---
let y, mo, d;
let m = text.match(/(20\d{2})[-.\/](\d{1,2})[-.\/](\d{1,2})/);
if (m) { y = +m[1]; mo = +m[2]; d = +m[3]; }
else {
  m = text.match(/(?:^|\s)(\d{1,2})\/(\d{1,2})(?=\s|$)/);
  if (m) { y = thisYear; mo = +m[1]; d = +m[2]; }
}
if (!m) {
  if (/내일/.test(text)) { const t = new Date(now.getTime() + 86400000); y = t.getFullYear(); mo = t.getMonth() + 1; d = t.getDate(); }
  else if (/오늘/.test(text)) { y = thisYear; mo = now.getMonth() + 1; d = now.getDate(); }
}
if (!y) {
  return { json: { parsed: false, reason: '날짜를 인식하지 못함 (YYYY-MM-DD 또는 MM/DD)', originalText: text } };
}

// --- 시간 ---
let sh, sm, eh, em;
let tm = text.match(/(\d{1,2}):(\d{2})\s*[~\-–]\s*(\d{1,2}):(\d{2})/);
if (tm) { sh = +tm[1]; sm = +tm[2]; eh = +tm[3]; em = +tm[4]; }
else {
  tm = text.match(/(?:^|[^\d:])(\d{1,2}):(\d{2})(?!\s*[~\-–]\s*\d)/);
  if (tm) { sh = +tm[1]; sm = +tm[2]; eh = (sh + 1) % 24; em = sm; }
}
let allDay = (sh === undefined);

// --- 날짜/시간 토큰 제거 헬퍼 ---
function stripDT(s) {
  return s
    .replace(/(20\d{2})[-.\/]\d{1,2}[-.\/]\d{1,2}/g, ' ')
    .replace(/\d{1,2}:\d{2}\s*[~\-–]\s*\d{1,2}:\d{2}/g, ' ')
    .replace(/\d{1,2}:\d{2}/g, ' ')
    .replace(/(?:^|\s)\d{1,2}\/\d{1,2}(?=\s|$)/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// --- 제목 ---
let summary = '';
let titleM = text.match(/(?:일정|제목|회의|미팅|스케줄)\s*[:：]\s*(.+)/);
if (titleM) {
  summary = stripDT(titleM[1].split(/\n/)[0])
    .replace(/장소\s*[:：].*/g, '')
    .replace(/@.*$/g, '')
    .replace(/[~\-–]\s*$/, '')
    .replace(/\s+/g, ' ').trim();
}
if (!summary) {
  summary = stripDT(text)
    .replace(/\/?(일정|제목|스케줄)\s*[:：]?/g, '')
    .replace(/오늘|내일/g, '')
    .replace(/장소\s*[:：].*/g, '')
    .replace(/@.*$/gm, '')
    .replace(/\s+/g, ' ').trim();
}
if (!summary) summary = '(제목 없음)';

// --- 장소 ---
let location = '';
let locM = text.match(/장소\s*[:：]\s*(.+)/);
if (locM) location = locM[1].split(/\n/)[0].trim();
else { locM = text.match(/@\s*(\S[^\n]*)/); if (locM) location = locM[1].trim(); }

// --- ISO ---
let startISO, endISO;
if (allDay) {
  startISO = `${y}-${pad(mo)}-${pad(d)}`;
  const dt = new Date(Date.UTC(y, mo - 1, d + 1));
  endISO = `${dt.getUTCFullYear()}-${pad(dt.getUTCMonth() + 1)}-${pad(dt.getUTCDate())}`;
} else {
  const sMin = sh * 60 + sm; const eMin = eh * 60 + em;
  if (eMin <= sMin) { eh = (sh + 1) % 24; em = sm; }
  startISO = `${y}-${pad(mo)}-${pad(d)}T${pad(sh)}:${pad(sm)}:00${TZ_OFFSET}`;
  endISO = `${y}-${pad(mo)}-${pad(d)}T${pad(eh)}:${pad(em)}:00${TZ_OFFSET}`;
}

return { json: { parsed: true, allDay, summary, location, start: startISO, end: endISO, originalText: text } };
